# Example: High vs Low Coupling in Python Concept

# HIGH COUPLING (Control & Common)
global_config = {'mode': 'fast'}

class Engine:
    def start(self, fuel_valve_flag):
        if fuel_valve_flag:
            print('Engine started')

# LOW COUPLING (Data)
class CleanEngine:
    def start(self, fuel_flow_rate: float) -> bool:
        if fuel_flow_rate > 0.0:
            return True
        return False

# Simple MVC (Model-View-Controller) Pattern Concept in Python

class Model:
    def get_data(self):
        return "Student: Rahul, Course: AI"

class View:
    def show_data(self, data):
        print(f"[VIEW] Displaying: {data}")

class Controller:
    def __init__(self, model, view):
        self.model = model
        self.view = view

    def update_view(self):
        data = self.model.get_data()
        self.view.show_data(data)

# Execution
m, v, c = Model(), View(), Controller(Model(), View())
c.update_view() # Controller coordinates Model and View

def check_grade(score):
    # White-box target: cover all branches
    if score >= 90:
        return "A"
    elif score >= 75:
        return "B"
    else:
        return "C"

# Test cases to achieve 100% Branch Coverage
print(check_grade(95)) # Triggers score >= 90
print(check_grade(80)) # Triggers score >= 75
print(check_grade(50)) # Triggers else block

